  const year=Number(today().slice(0,4)); const [v,setV]=useState<Plan>(existing?snapshot(existing):{id:newId("AP"),name:"",start:year,end:year,areas:["Health & Safety"],notes:"",active:true}),[error,setError]=useState("");
