  const rows=forms.filter(f=>f.target==="Audit"&&f.status==="Published"&&f.name.toLowerCase().includes(query.toLowerCase())&&(!site||!f.auditSettings?.siteIds.length||f.auditSettings.siteIds.includes(site))),form=rows.find(f=>f.id===selected)||rows[0];
